mapper.select:

SELECT d.id, d.no, d.kind, d.doc_type, d.status, d.version, d.company_id,
       COALESCE(d.to_warehouse_id, d.from_warehouse_id) AS warehouse_id, w.name AS warehouse_name,
       d.prd_receipt_id AS receipt_id, r.no AS receipt_no, p.no AS prd_order_no, p.kind AS prd_order_kind,
       f.short_name AS factory_name, d.order_id, o.no AS order_no, d.reason, d.ship_to, d.logistics_no,
       d.doc_date, d.remark, d.create_by, d.audit_by, d.create_time,
       agg.first_sku_id, agg.style_count, agg.total_qty, agg.total_amount
FROM fg_doc d
JOIN bas_warehouse w ON w.id = COALESCE(d.to_warehouse_id, d.from_warehouse_id)
LEFT JOIN prd_receipt r ON r.id = d.prd_receipt_id
LEFT JOIN prd_order p ON p.id = r.prd_order_id
LEFT JOIN sup_supplier f ON f.id = p.factory_id
LEFT JOIN ord_order o ON o.id = d.order_id
LEFT JOIN LATERAL (SELECT (array_agg(i.style_sku_id ORDER BY i.seq, i.id))[1] AS first_sku_id,
                          COUNT(DISTINCT k.style_id) AS style_count, SUM(i.qty) AS total_qty, SUM(i.amount) AS total_amount
                   FROM fg_doc_item i JOIN sty_style_sku k ON k.id = i.style_sku_id
                   WHERE i.doc_id = d.id) agg ON true
WHERE d.kind = #{q.kind}
AND d.create_by = #{scope.userId}
AND d.doc_type = #{q.docType}

    AND d.status IN #{s}

AND (d.from_warehouse_id = #{q.warehouseId} OR d.to_warehouse_id = #{q.warehouseId})
AND p.factory_id = #{q.factoryId}
AND d.order_id = #{q.orderId}

    AND EXISTS (SELECT 1 FROM fg_doc_item si JOIN sty_style_sku sk ON sk.id = si.style_sku_id
                WHERE si.doc_id = d.id AND sk.style_id = #{q.styleId})

AND d.doc_date >= #{q.docDateFrom}
AND d.doc_date <= #{q.docDateTo}

    AND d.id IN #{id}




            AND (upper(d.no) IN #{c}
                 OR upper(r.no) IN #{c}
                 OR upper(o.no) IN #{c})


            AND (upper(d.no) LIKE #{kw} OR upper(r.no) LIKE #{kw} OR upper(p.no) LIKE #{kw} OR upper(o.no) LIKE #{kw}
                 OR upper(d.logistics_no) LIKE #{kw}
                 OR EXISTS (SELECT 1 FROM fg_doc_item ki JOIN sty_style_sku kk ON kk.id = ki.style_sku_id
                            JOIN sty_style ks ON ks.id = kk.style_id
                            WHERE ki.doc_id = d.id AND (upper(ks.code) LIKE #{kw} OR upper(kk.code) LIKE #{kw})))



ORDER BY d.id DESC


SELECT r.id AS receipt_id, r.no AS receipt_no, p.id AS prd_order_id, p.no AS prd_order_no, p.kind AS prd_order_kind,
       p.style_id, s.code AS style_code, s.name AS style_name, p.factory_id, f.short_name AS factory_name,
       t.qty, t.defect_qty, t.qty - t.defect_qty AS good_qty, COALESCE(st.qty, 0) AS stocked_qty,
       t.qty - t.defect_qty - COALESCE(st.qty, 0) AS remain_qty,
       r.warehouse_id, w.name AS warehouse_name, r.receipt_date

AND p.factory_id = #{q.factoryId}
AND r.receipt_date >= #{q.receiptDateFrom}
AND r.receipt_date <= #{q.receiptDateTo}



            AND (upper(r.no) IN #{c}
                 OR upper(p.no) IN #{c}
                 OR upper(s.code) IN #{c})

        AND (upper(r.no) LIKE #{kw} OR upper(p.no) LIKE #{kw} OR upper(s.code) LIKE #{kw})


ORDER BY r.receipt_date, r.id
